import { buildVaultsBalance, VaultsModule } from "haedal-vault-sdk";
import { convertPrecision, extractGenericTypes, getPrice, safeMul } from "."
import { SuiClient } from "@mysten/sui/dist/cjs/client";
import { tokenList } from "../config";


export const getVaultPoolPrice = async (vaultPool: any, coinDetail: { decimals: number; }, vaultSDK: VaultsModule) => {
    const { pool, clmmPool } = await vaultSDK.getVaultAndPool(vaultPool.id, true)
    const vaultData = buildVaultsBalance('0x0', pool.lp_token_treasury, JSON.parse(JSON.stringify(pool)), JSON.parse(JSON.stringify(clmmPool)))
    const { amount_a = '0', amount_b = '0', lp_token_balance = '0' } = vaultData
    const aAmount = Number(convertPrecision(amount_a, vaultPool.coinADetail.decimals, 'div')) * vaultPool.coinADetail.price
    const bAmount = Number(convertPrecision(amount_b, vaultPool.coinBDetail.decimals, 'div')) * vaultPool.coinBDetail.price
    const price = (aAmount + bAmount) / (Number(lp_token_balance) / 10 ** coinDetail.decimals)
    return price || 1
}

export const formatFarmingData = async (farmingList: any[], vaultSDK: VaultsModule) => {
    const results = await Promise.all(farmingList.map(async (pool: any) => {
        const { stakeCoinType, poolId, coinDetail, rewardConfigs, vaultPool } = pool
        let poolEnded = true
        let rewardItemBalance = 0
        let rewardItemAmount = 0

        let price = Number(coinDetail.price || 1) || 1
        let vaultApy = 0
        if (vaultPool) {
            price = await getVaultPoolPrice(vaultPool, coinDetail, vaultSDK)
            vaultApy = vaultPool ? safeMul(Number(vaultPool.apy), 100) || 0 : 0
        }

        const balance = Number(convertPrecision((Number(pool.balance || 0)) + '', coinDetail.decimals, 'div'))
        const balanceAmount = balance * price
        let rewardTotalApr = 0
        const newRewardConfigs = rewardConfigs.filter((rewardConfig: any) => rewardConfig.rate && Number(rewardConfig.rate))
        newRewardConfigs.forEach((rewardConfig: any) => {
            rewardConfig.coinDetail.price = Number(rewardConfig.coinDetail.price) || 1
            rewardConfig.curRate = Number(rewardConfig.rate || 0)
            rewardConfig.apr = ((rewardConfig.curRate * 60 * 60 * 24 * 365 / (10 ** rewardConfig.coinDetail.decimals)) * rewardConfig.coinDetail.price) * 100 / balanceAmount
            rewardTotalApr += rewardConfig.apr
            rewardItemBalance += rewardConfig.curRewardBalance
            rewardItemAmount += rewardConfig.curRewardAmount
            if (rewardConfig.curRate > 0) {
                poolEnded = false
            }
        })

        return {
            ...pool,
            poolId,
            stakeCoinType,
            coinDetail,
            balance: Number(balance),
            balanceAmount,
            rewardTotalApr,
            vaultApy: vaultApy,
            totalApr: vaultApy + rewardTotalApr,
            ended: poolEnded,
            rewardItemAmount,
            rewardItemBalance,
            rewardConfigs: newRewardConfigs,
            vaultPool,
            price
        }
    }))
    return results
}

export const getCoinInfo = async (suiClient: SuiClient, coinType: string, isLPToken?: boolean | null) => {
    try {
        const coinDetail = await suiClient.getCoinMetadata({
            coinType: coinType
        })
        const coinInfo: any = tokenList.find(i => coinType === i.coin_type) || {}
        let price = 1
        const [curPrice] = !isLPToken && coinInfo.pythId ? await getPrice([coinInfo.pythId]) : [1]
        price = Number(curPrice)
        return {
            ...coinDetail,
            price: price,
        }
    } catch (error) {
        console.log('getCoinInfo error', error)
    }
}

export const getVaultPool = async (suiClient: SuiClient, vaultList: any[], stakeCoinType: string) => {
    const vaultPoolInfo: any = vaultList.find((item: any) => item.lpTokenTreasury === stakeCoinType)
    if (!vaultPoolInfo) return
    const coinADetail = await getCoinInfo(suiClient, vaultPoolInfo.coin_type_a)
    const coinBDetail = await getCoinInfo(suiClient, vaultPoolInfo.coin_type_b)
    return {
        apr: vaultPoolInfo.apr,
        apy: vaultPoolInfo.apy,
        coinADetail,
        coinBDetail,
        fee_rate: vaultPoolInfo.fee_rate,
        id: vaultPoolInfo.id,
    }
}

export const formateFarmingClientData = async (farmingList: any[], suiClient: SuiClient) => {
    const results = await Promise.all(farmingList.map(async (poolData: any) => {
        const { objectId: poolId, type, content: { fields: { balance, active, reward_configs } } } = poolData as any
        const stakeCoinType = extractGenericTypes(type)
        const coinDetail = await getCoinInfo(suiClient, stakeCoinType, true)
        const { fields: { contents: defaultRewardConfigs } } = reward_configs
        const rewardConfigs = await Promise.all(defaultRewardConfigs.map(async (reward_config: { fields: { key: { fields: { name: string } }; value: { fields: object } } }) => {
            const nowTime = new Date().getTime()
            const rewardConfig: any = {
                rewardCoinType: '0x' + reward_config.fields?.key?.fields?.name,
                ...reward_config.fields.value.fields
            }
            rewardConfig.coinDetail = await getCoinInfo(suiClient, rewardConfig.rewardCoinType)
            const { rate_change_at, reward_rate_before, reward_rate_after } = rewardConfig
            if (nowTime >= rate_change_at * 1000) {
                rewardConfig.curRate = Number(reward_rate_after || 0)
            } else {
                rewardConfig.curRate = Number(reward_rate_before || 0)
            }
            return {
                ...rewardConfig,
                rewardCoinType: rewardConfig.rewardCoinType,
                bank: rewardConfig?.bank || '',
                coinDetail: rewardConfig.coinDetail,
                rate: rewardConfig.curRate
            }
        }))
        return {
            active: active,
            balance: Number(balance),
            coinDetail,
            poolId,
            rewardConfigs,
            stakeCoinType
        }

    }))
    return results
}