import { SuiClient } from '@mysten/sui/client'
import { SuiClient as NewClient } from "@mysten/sui/client"
import { farmsConfigs } from './types'
import { FarmsModule } from './modules/farmsModule'
import VolatileVaultsSDK, { initVaultSDK, VaultsModule } from 'haedal-vault-sdk'

export type SdkOptions = {
  fullRpcUrl: string
  env: 'mainnet' | 'testnet',
  farms: farmsConfigs
}

export class FarmsSDK {

  protected _sdkOptions: SdkOptions

  protected _suiClient: SuiClient

  protected _newSuiClient: any

  protected _farms: FarmsModule

  protected _vaults: VolatileVaultsSDK

  protected _senderAddress = ''
  constructor(options: SdkOptions) {
    this._sdkOptions = options
    this._suiClient = new SuiClient({ url: options.fullRpcUrl })
    this._vaults = initVaultSDK({ env: options.env, fullNodeUrl: options.fullRpcUrl })
    this._farms = new FarmsModule(this)
  }
  get sdkOptions(): SdkOptions {
    return this._sdkOptions
  }

  get Farms(): FarmsModule {
    return this._farms
  }

  get Vaults(): VaultsModule {
    return this._vaults.Vaults
  }

  get SuiClient(): SuiClient {
    return this._suiClient
  }

  get senderAddress(): string {
    return this._senderAddress
  }

  set senderAddress(value: string) {
    this._senderAddress = value
  }

}