import { initMainnetSDK, initTestnetSDK } from "."
import { FarmsSDK } from "../sdk"

export enum SdkEnv {
    mainnet = 'mainnet',
    testnet = 'testnet',
}

interface InitSDKOptions {
    env: 'mainnet' | 'testnet'
    fullNodeUrl?: string
}

export function initFarmsSDK(options: InitSDKOptions): FarmsSDK {
    const { env, fullNodeUrl } = options
    return env === SdkEnv.mainnet ? initMainnetSDK(fullNodeUrl) : initTestnetSDK(fullNodeUrl)
}